import{_ as a,o,c as t,ag as c}from"./chunks/framework.DFzRwoE6.js";const h=JSON.parse('{"title":"软件测试：Mock","description":"","frontmatter":{"title":"软件测试：Mock"},"headers":[],"relativePath":"01-full-stack/python/web-testing.md","filePath":"01-full-stack/python/web-testing.md"}'),l={name:"01-full-stack/python/web-testing.md"};function r(i,e,n,k,m,s){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="软件测试-mock" tabindex="-1">软件测试：Mock <a class="header-anchor" href="#软件测试-mock" aria-label="Permalink to &quot;软件测试：Mock&quot;">​</a></h1><h2 id="mock-含义" tabindex="-1">mock 含义 <a class="header-anchor" href="#mock-含义" aria-label="Permalink to &quot;mock 含义&quot;">​</a></h2><p>测试的对象一般称之为SUT(Software Under Test) mock 即模拟/仿真，SUT 的依赖（dependency）。换句话说，mock 的作用是模拟 SUT 依赖对象的行为。类似在汽车测试中的相关ECU 仿真。</p><h2 id="mock-级别" tabindex="-1">mock 级别 <a class="header-anchor" href="#mock-级别" aria-label="Permalink to &quot;mock 级别&quot;">​</a></h2><p>（1）方法级别 mock：mock 的对象是一个函数调用，例如获取系统环境变量。</p><p>（2）类级别 mock：mock 的对象是一个类，例如一个 HTTP server。</p><p>（3）接口级别 mock：mock 的对象是一个 API 接口。</p><p>（4）服务级别 mock：mock 的对象是整个服务。比如前端工程师自测试时，可以讲后端整个服务都 mock 掉，这其实等同于将后端的所有接口都 mock。</p><h2 id="mock-方式" tabindex="-1">mock 方式 <a class="header-anchor" href="#mock-方式" aria-label="Permalink to &quot;mock 方式&quot;">​</a></h2><ul><li>APIs请求构造</li><li>本地配置</li><li>配置中心</li><li>反向代理</li><li>前向代理</li></ul><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><ul><li><a href="https://blog.csdn.net/g6U8W7p06dCO99fQ3/article/details/114324301" target="_blank" rel="noreferrer">mock 技术 - CSDN</a></li></ul>',12)])])}const p=a(l,[["render",r]]);export{h as __pageData,p as default};
